A. Updates T3 (Like / Save / Share click feedback) to mirror the PHYSICS-based-effects demo instead of the elastic / back.out ease the original plan used. NEW T3 DEMO: {"url":"https://demos.gsap.com/demo/create-physics-based-effects/","title":"Create physics-based effects","technique":"Physics2DPlugin for projectile motion (gravity + velocity + angle + friction). The demo itself is a particle/projectile launcher — not directly a button click micro-interaction. The transferable idea for Like/Save/Share is the broader GSAP "physics-based effects" toolkit: Physics2DPlugin for confetti/particle bursts on tap, plus CustomBounce + CustomEase for the tactile button rebound itself. The recommended port combines both: a CustomBounce squish-and-rebound on the button transform, layered with an optional Physics2D particle burst on tap (great for Like), and a per-button CSS-variable color flash driven by the same timeline.","keyMechanic":"Physics2DPlugin animates `physics2D: { velocity, angle, gravity, friction }` on each tick — it integrates position from velocity/gravity rather than tweening to a fixed endpoint, which is what makes it feel "real". For the button feedback, you (a) overshoot the scale with CustomBounce.create("myBounce", { strength: 0.6, endAtStart: true, squash: 2 }) so the button squishes, snaps back, and settles, (b) flash a per-element CSS variable (--flash-color) to that button's brand color using gsap.fromTo on the variable so it's keyframed, and (c) optionally spawn N short-lived particle divs and animate each with `physics2D` for a confetti burst (Like only). All three are merged into one gsap.timeline() so the tactile feel, color flash, and burst stay in lockstep.","gsapPlugins":["Physics2DPlugin","CustomBounce","CustomEase"],"isPaidPlugin":false,"fetchSuccess":true,"codeSnippet":"// gsap-button-feedback.js
import { gsap } from "gsap";
import { Physics2DPlugin } from "gsap/Physics2DPlugin";
import { CustomBounce } from "gsap/CustomBounce";
import { CustomEase } from "gsap/CustomEase";

gsap.registerPlugin(Physics2DPlugin, CustomBounce, CustomEase);

// Register a tactile bounce once at module scope
CustomBounce.create("btnBounce", { strength: 0.55, endAtStart: false, squash: 1.4 });

/**
 * Tactile click feedback for a single button.
 * @param {HTMLElement} el      - the button
 * @param {string}      flash   - CSS color for the per-button flash (e.g. var(--like))
 * @param {boolean}     burst   - true for Like (spawn confetti particles)
 */
export function pressFeedback(el, flash, burst = false) {
  const tl = gsap.timeline({ defaults: { overwrite: "auto" } });

  // 1. Physics-y squish & rebound on transform (CustomBounce)
  tl.fromTo(el,
    { scale: 0.86, y: 2 },
    { scale: 1, y: 0, duration: 0.9, ease: "btnBounce" },
    0
  );
  // squashY runs slightly behind so the button "lands" then settles
  tl.fromTo(el,
    { scaleY: 0.78, scaleX: 1.12 },
    { scaleY: 1, scaleX: 1, duration: 0.9, ease: "btnBounce-squash" },
    0
  );

  // 2. Per-button color flash via CSS variable on the element itself
  // Each button sets its own --flash-color in CSS; here we override inline
  // and tween it back to transparent so the ring/glow fades on the SAME timeline.
  el.style.setProperty("--flash-color", flash);
  tl.fromTo(el,
    { "--flash-alpha": 0.85 },
    { "--flash-alpha": 0, duration: 0.55, ease: CustomEase.create("flashOut", "M0,0 C0.2,1 0.3,1 1,1") },
    0.02
  );

  // 3. Optional Physics2D confetti burst (Like only)
  if (burst) {
    const rect = el.getBoundingClientRect();
    const host = el.ownerDocument.body;
    for (let i = 0; i < 14; i++) {
      const p = host.appendChild(document.createElement("span"));
      p.className = "fx-particle";
      p.style.cssText = `
        position:fixed;left:${rect.left + rect.width / 2}px;top:${rect.top + rect.height / 2}px;
        width:6px;height:6px;border-radius:999px;background:${flash};pointer-events:none;z-index:9999;`;
      tl.to(p, {
        physics2D: {
          velocity: gsap.utils.random(260, 420),
          angle:    gsap.utils.random(-110, -70),  // upward fan
          gravity:  900,
          friction: 0.06,
        },
        opacity: 0,
        scale: 0.4,
        duration: 0.9,
        ease: "power1.out",
        onComplete: () => p.remove(),
      }, 0);
    }
  }
  return tl;
}","reactPort":"// ReadingViewActions.tsx
import { useRef } from "react";
import { useGSAP } from "@gsap/react";
import { gsap } from "gsap";
import { Physics2DPlugin } from "gsap/Physics2DPlugin";
import { CustomBounce } from "gsap/CustomBounce";
import { CustomEase } from "gsap/CustomEase";
import { pressFeedback } from "./gsap-button-feedback";

gsap.registerPlugin(useGSAP, Physics2DPlugin, CustomBounce, CustomEase);

export function ReadingViewActions({ onLike, onSave, onShare }) {
  const scope = useRef<HTMLDivElement>(null);

  // Register the named bounce exactly once inside scope
  useGSAP(() => {
    CustomBounce.create("btnBounce", { strength: 0.55, squash: 1.4, endAtStart: false });
  }, { scope });

  const { contextSafe } = useGSAP({ scope });

  const handleLike  = contextSafe!((e) => { pressFeedback(e.currentTarget, "var(--like)",  true ); onLike(); });
  const handleSave  = contextSafe!((e) => { pressFeedback(e.currentTarget, "var(--gold)",  false); onSave(); });
  const handleShare = contextSafe!((e) => { pressFeedback(e.currentTarget, "var(--ink-2)", false); onShare(); });

  return (
    <div ref={scope} className="reading-actions">
      <button className="rv-btn rv-like"  style={{ ["--flash-color" as any]: "var(--like)" }}  onClick={handleLike}>Like</button>
      <button className="rv-btn rv-save"  style={{ ["--flash-color" as any]: "var(--gold)" }}  onClick={handleSave}>Save</button>
      <button className="rv-btn rv-share" style={{ ["--flash-color" as any]: "var(--ink-2)" }} onClick={handleShare}>Share</button>
    </div>
  );
}

/* CSS — each button reads --flash-color + --flash-alpha; the tween drives alpha back to 0
.rv-btn {
  --flash-alpha: 0;
  position: relative; isolation: isolate;
  transform-origin: 50% 60%;             // bias rebound toward thumb contact
  will-change: transform;
}
.rv-btn::after {
  content: ""; position: absolute; inset: -2px; border-radius: inherit;
  background: var(--flash-color); opacity: var(--flash-alpha);
  filter: blur(6px); z-index: -1; pointer-events: none;
  transition: none;                       // GSAP owns this var
}
.rv-like  { --like: #ff3860; }
.rv-save  { --gold: #d4a24a; }
.rv-share { --ink-2: rgba(255,255,255,0.55); }
*/","a11yNotes":"- The feedback is purely additive: the React onClick still fires synchronously, so screen reader / keyboard users get identical behavior. The timeline is fire-and-forget. - Wrap the entire effect in `if (!gsap.matchMedia().reduced) { ... }` or check `window.matchMedia('(prefers-reduced-motion: reduce)').matches` and, when true, skip the squish/burst and just toggle `--flash-alpha` to 0.6 for 120ms via a single non-bouncy tween — color feedback remains, motion does not. - Particles get `pointer-events:none` and are removed onComplete so they never trap focus or block taps. - Use `transform-origin: 50% 60%` so the rebound visually anchors at the thumb, which reads as more "tactile" without affecting hit-target geometry. - Color choice for Like (#ff3860) and Save (#d4a24a) should be checked against the reading-view background for 3:1 non-text contrast (WCAG 1.4.11); the blurred glow alone is decorative, but if it's the only feedback in reduced-motion mode it must meet contrast. - Buttons keep their `:focus-visible` ring untouched — the ::after layer sits behind (z-index: -1) so it never masks the focus outline. - For the Like burst, particles are fixed-position but absolute-removed onComplete; they will not affect document flow, layout shift (CLS), or assistive-tech tree (they're empty spans)."}

