import { useEffect } from "react";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { ScrollToPlugin } from "gsap/ScrollToPlugin";

gsap.registerPlugin(useGSAP, ScrollToPlugin);

/**
 * Smoothly animate the window scroll to a saved reading position.
 * Drop-in upgrade for the `window.scrollTo({ top, behavior: "instant" })`
 * call at line 119 of frontend/lib/useReadingPosition.ts.
 *
 * Behavior parity with the GSAP demo:
 *   - ScrollToPlugin (free, core plugin — NOT a Club GSAP paid plugin)
 *   - duration: 1.1s   (demo uses 1; reading-restore feels slightly better at 1.1)
 *   - ease:     power2.inOut  (demo omits ease → defaults to power1.out; we upgrade)
 *   - autoKill: true   (default for window targets — user scroll instantly aborts tween)
 *   - prefers-reduced-motion → instant jump fallback
 */
export function smoothRestoreScroll(
  targetY: number,
  opts?: { onSettled?: () => void },
) {
  if (typeof window === "undefined") return;

  const reduced = window.matchMedia?.(
    "(prefers-reduced-motion: reduce)",
  ).matches;

  if (reduced) {
    window.scrollTo({ top: targetY, behavior: "instant" as ScrollBehavior });
    opts?.onSettled?.();
    return;
  }

  // rAF settles layout (images, fonts) before measuring/animating —
  // mirrors the existing rAF guard in useReadingPosition.ts (~line 96).
  requestAnimationFrame(() => {
    gsap.to(window, {
      scrollTo: { y: targetY, autoKill: true },
      duration: 1.1,
      ease: "power2.inOut",
      overwrite: "auto",
      onAutoKill: () => opts?.onSettled?.(),
      onComplete: () => opts?.onSettled?.(),
      onInterrupt: () => opts?.onSettled?.(),
    });
  });
}

/* --------------------------------------------------------------
 * useGSAP variant — call from inside a "use client" component
 * so the tween is auto-cleaned on unmount / strict-mode rerun.
 * -------------------------------------------------------------- */
export function useSmoothRestoreOnMount(
  targetY: number | null,
  ready: boolean,
) {
  useGSAP(
    () => {
      if (!ready || targetY == null) return;
      const reduced = window.matchMedia?.(
        "(prefers-reduced-motion: reduce)",
      ).matches;
      if (reduced) {
        window.scrollTo({ top: targetY, behavior: "instant" as ScrollBehavior });
        return;
      }
      gsap.to(window, {
        scrollTo: { y: targetY, autoKill: true },
        duration: 1.1,
        ease: "power2.inOut",
      });
    },
    { dependencies: [ready, targetY] },
  );
}","a11yNotes":"CRITICAL — respect prefers-reduced-motion. The provided React port branches on window.matchMedia('(prefers-reduced-motion: reduce)') and falls back to the existing instant window.scrollTo when a user has reduced motion enabled. Animating ~1s of vertical scroll is a known vestibular trigger.

autoKill: true is itself an a11y win. Keyboard users (PageDown, Space, arrow keys) and assistive-tech users who scroll mid-restore are NEVER fought by the animation — ScrollToPlugin detects the manual scroll attempt and instantly aborts the tween. This is the single most important reason to prefer ScrollToPlugin over a hand-rolled rAF tween or CSS scroll-behavior: smooth (which has no equivalent auto-abort).

For screen-reader users the visual restore is cosmetic. If the saved reading position corresponds to a known anchor (heading id, paragraph id), additionally call element.focus({ preventScroll: true }) after the tween settles so the SR cursor lands where the visual cursor is. Do not trap focus or add a pointer-events:none overlay during the tween — you don't need to, because autoKill handles user input gracefully.

Do not lower the contrast or animate the article body during the scroll — keep all motion confined to the scroll position itself. Compound motion (scroll + fade + transform) compounds vestibular load."}

C. Updates T5 (tag filter) to mirror the flexbox-filtering demo. NEW T5 DEMO: {"url":"https://demos.gsap.com/demo/flexbox-filtering/","title":"Smooth Flexbox Filtering with Flip (GreenSock CodePen NWRxarv)","technique":"FLIP (First-Last-Invert-Play) reflow animation. Capture the bounding-box state of every card BEFORE the filter mutation, mutate the DOM (toggle each card's display between "inline-flex" and "none" so flexbox reflows the visible set), then call Flip.from(state, ...). Flip diffs the new positions/sizes against the snapshot, instantly inverts every visible card back to its old spot, and animates the removal of those offsets so cards slide into their new flex slots. onEnter handles items that re-entered the flow (fade+scale in), onLeave handles items that left (fade+scale out), with absolute:true holding leavers in their old slot during the tween so the surviving cards don't fight a layout shift mid-animation.","keyMechanic":"Three-step lifecycle on every checkbox click: (1) state = Flip.getState(items) snapshots all 8 .item rects; (2) items.forEach(item =&gt; item.style.display = matches.indexOf(item) === -1 ? "none" : "inline-flex") — this is what makes flexbox re-pack the visible cards into a tight grid; (3) Flip.from(state, { duration: 0.7, scale: true, ease: "power1.inOut", stagger: 0.08, absolute: true, onEnter: els =&gt; gsap.fromTo(els,{opacity:0,scale:0},{opacity:1,scale:1,duration:1}), onLeave: els =&gt; gsap.to(els,{opacity:0,scale:0,duration:1}) }) tweens everything. absolute:true is the load-bearing option — it lifts the leaving cards to position:absolute for the duration of the flip so the staying cards can flow into their new flex positions without their tween being clobbered by the same reflow.","gsapPlugins":["gsap","Flip"],"isPaidPlugin":false,"fetchSuccess":true,"codeSnippet":"// === VERBATIM from CodePen GreenSock/NWRxarv "Smooth Flexbox Filtering with Flip"
// Plugins loaded (CDN): gsap-latest-beta.min.js + Flip.min.js
// HTML: .container > .buttons-container > .checkboxes > 4x label.tag-button (input#all, input.filter#gradient-blue|pink|purple)
//                 + .box-container > 8x div.item.gradient-{blue|pink|purple}
// (display:flex; flex-wrap:wrap on .box-container — the flex reflow is what Flip animates)

const allCheckbox = document.querySelector('#all'),
      filters = gsap.utils.toArray('.filter'),
      items = gsap.utils.toArray('.item');

function updateFilters() {
  const state = Flip.getState(items), // get the current state
        classes = filters.filter(checkbox => checkbox.checked).map(checkbox => "." + checkbox.id),
        matches = classes.length ? gsap.utils.toArray(classes.join(",")) : classes;

  // adjust the display property of each item ("none" for filtered ones, "inline-flex" for matching ones)
  items.forEach(item => item.style.display = matches.indexOf(item) === -1 ? "none" : "inline-flex");

  // animate from the previous state
  Flip.from(state, {
    duration: 0.7,
    scale: true,
    ease: "power1.inOut",
    stagger: 0.08,
    absolute: true,
    onEnter: elements => gsap.fromTo(elements, {opacity: 0, scale: 0}, {opacity: 1, scale: 1, duration: 1}),
    onLeave: elements => gsap.to(elements, {opacity: 0, scale: 0, duration: 1})
  });

  // Update the all checkbox:
  allCheckbox.checked = matches.length === items.length;
}

filters.forEach(btn => btn.addEventListener('click', updateFilters));
allCheckbox.addEventListener('click', () => {
  filters.forEach(checkbox => checkbox.checked = allCheckbox.checked);
  updateFilters();
});","reactPort":"// CRITICAL CAVEAT for Lucifer's Diary:
// frontend/components/TagBar.tsx uses <Link href={`${basePath}?tagIds=${id}`}>, so a tag click triggers a
// full App Router navigation. The card list on /browse, /search, /tag/[slug] is rendered server-side
// from new searchParams — the DOM tree for the cards is REPLACED, not mutated. Flip.getState captures
// nodes by reference; after the navigation those node refs are gone, so the verbatim demo pattern
// CANNOT survive the navigation as-is. You have three escape hatches:
//
// (A) [RECOMMENDED] Client-side filter on already-fetched data. Convert the cards container to a
//     client component that receives the full result set once, then filter in memory off URL state.
//     Keeps SSR-friendly URLs while letting the same DOM nodes persist across filter changes.
//
// (B) Bridge Flip across the navigation with sessionStorage. Snapshot Flip.getState() into
//     Flip.getState(items).clone()/JSON before router.push, then on the next render call
