export function CardGrid({ allCards }: { allCards: Card[] }) {
  const containerRef = useRef<HTMLDivElement>(null);
  const params = useSearchParams();
  const activeTagIds = params.get("tagIds")?.split(",").filter(Boolean) ?? [];

  // visibility map drives both render output AND the Flip mutation
  const visible = (c: Card) =>
    activeTagIds.length === 0 || c.tags.some((t) => activeTagIds.includes(t.id));

  // useGSAP with a dependency on activeTagIds runs Flip on EVERY filter change.
  // contextSafe + revertOnUpdate cleans up tweens between renders so rapid
  // clicks don't stack conflicting animations on the same nodes.
  useGSAP(
    () => {
      const items = gsap.utils.toArray<HTMLElement>(".card", containerRef.current);
      if (!items.length) return;

      // BEFORE-state snapshot — this is the LAYOUT-EFFECT moment: useGSAP runs after
      // the DOM has the NEW visibility classes applied by React's render, so we
      // need to snapshot from the *previous* render. The trick: snapshot inside a
      // useGSAP "dependencies" run BEFORE you mutate display. The cleanest way is
      // to snapshot synchronously in a ref before the re-render, then animate from it.
      // See pattern in https://gsap.com/docs/v3/Plugins/Flip/static.getState() — for React,
      // you typically snapshot in a useLayoutEffect that runs BEFORE the commit, OR
      // toggle a class instead of unmounting so the same nodes survive across renders.
      Flip.from(stateRef.current, {
        duration: 0.7,
        scale: true,
        ease: "power1.inOut",
        stagger: 0.08,
        absolute: true,
        onEnter: (els) =>
          gsap.fromTo(els, { opacity: 0, scale: 0 }, { opacity: 1, scale: 1, duration: 0.7 }),
        onLeave: (els) => gsap.to(els, { opacity: 0, scale: 0, duration: 0.7 }),
      });
    },
    { scope: containerRef, dependencies: [activeTagIds.join(",")] }
  );

  // Render ALL cards every time, just toggle a .is-hidden class (display:none in CSS)
  // so DOM nodes persist across filter changes and Flip can match them by ref.
  return (
    <div ref={containerRef} className="card-grid">
      {allCards.map((c) => (
        <article
          key={c.id}
          data-flip-id={c.id}                       /* stable identity for Flip */
          className={`card ${visible(c) ? "" : "is-hidden"}`}
        >
          {/* card content */}
        </article>
      ))}
    </div>
  );
}

