// Single place to import gsap from. Plugins are registered exactly once,
// guarded against SSR — gsap must never run on the server.
//
// Always import from here, never directly from 'gsap', so plugins are
// guaranteed to be registered before use.

import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

if (typeof window !== 'undefined') {
  gsap.registerPlugin(ScrollTrigger);
}

/**
 * Honors the user's OS-level "reduce motion" preference. Components
 * that run reveal / stagger animations should bail out early when
 * this returns true. Always returns false on the server (no signal
 * available) so SSR markup matches the un-animated final state.
 */
export function prefersReducedMotion(): boolean {
  if (typeof window === 'undefined') return false;
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

